import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Commit } from '../types'
import { LOG_FORMAT, mergeCommits, parseLog } from './lib/commits'

const PANE = 'feature-tracker'

const since = atom({ plugin: 'feature-tracker', key: 'since' } as const, null)
const commits = atom({ plugin: 'feature-tracker', key: 'commits' } as const, [])
const branch = atom({ plugin: 'feature-tracker', key: 'branch' } as const, '')
const onlyFeatures = atom({ plugin: 'feature-tracker', key: 'onlyFeatures' } as const, true)
const error = atom({ plugin: 'feature-tracker', key: 'error' } as const, false)

const TEXT = {
  en: {
    title: 'Features',
    features: 'Features',
    all: 'All commits',
    refresh: 'refresh',
    on: 'on',
    empty: 'No commits in this session yet.',
    emptyFeatures: 'No feat commits yet. Switch to "All commits" to see the rest.',
    noRepo: 'This folder is not a git repository.',
    opened: 'Features pane opened.',
  },
  pt: {
    title: 'Features',
    features: 'Features',
    all: 'Todos os commits',
    refresh: 'atualizar',
    on: 'em',
    empty: 'Nenhum commit nesta sessão ainda.',
    emptyFeatures: 'Nenhum commit feat ainda. Troque para "Todos os commits" para ver o resto.',
    noRepo: 'Esta pasta não é um repositório git.',
    opened: 'Painel de features aberto.',
  },
}

// Cor de cada tipo de commit (tokens do tema); o resto fica apagado.
const TYPE_COLOR: Record<string, string> = { feat: 'success', fix: 'warning', perf: 'permission', refactor: 'permission' }

// Painel em cinza quase preto (como o fundo do terminal do Claude), texto claro e cinza neutro legível para o secundário.
const BG = '#171717'
const FG = '#e8e8e8'
const MUTED = '#9b9b9b'

const two = (n: number) => String(n).padStart(2, '0')
const clock = (ms: number) => {
  const d = new Date(ms)
  return `${two(d.getDate())}/${two(d.getMonth() + 1)} ${two(d.getHours())}:${two(d.getMinutes())}`
}

// Relê o git: commits desde o começo da sessão, na branch atual.
async function sync($: EngineInterface) {
  const startedAt = await read($, since)
  if (startedAt === null) return
  try {
    const [log, head] = await Promise.all([
      $.process.run(['git', 'log', '--no-merges', `--since=${new Date(startedAt).toISOString()}`, `--format=${LOG_FORMAT}`]),
      $.process.run(['git', 'rev-parse', '--abbrev-ref', 'HEAD']),
    ])
    if (log.exitCode !== 0 || head.exitCode !== 0) throw new Error('git')
    const current = head.stdout.trim()
    await update($, branch, () => current)
    await update($, commits, known => mergeCommits(known, parseLog(log.stdout, current)))
    await update($, error, () => false)
  } catch {
    await update($, error, () => true)
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'features', description: 'Show the commits of this session: features, fixes, hashes and branches' })
    if ((await read($, since)) === null) await update($, since, () => Date.now())
    await sync($)
    return next(e)
  })

  on('command.run', { command: 'features' }, async $ => {
    await sync($)
    await $.ui.open({ id: PANE, title: 'Features' })
    const lng = (await $.env.get('LANG'))?.toLowerCase().startsWith('pt') ? 'pt' : 'en'
    return { text: TEXT[lng].opened }
  })

  // Depois de qualquer Bash que mexa com git, relê (commit, checkout, pull...).
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    if (/\bgit\b/.test(e.command)) await sync($)
    return ran
  })

  // Botão clicável acima do prompt, à direita: abre o painel e mostra quantas features já saíram.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const count = (await read($, commits)).filter(c => c.type === 'feat').length
    const label = `◆ Features · ${count}`
    return (
      <Box>
        <Box flexGrow={1} />
        <Button key="open-features" plain label={label} onPress={() => $.ui.open({ id: PANE, title: 'Features' })}>
          <Text color="claude" bold>{label}</Text>
          <Text dimColor>{' ▲'}</Text>
        </Button>
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const t = TEXT[(await $.env.get('LANG'))?.toLowerCase().startsWith('pt') ? 'pt' : 'en']
    const [list, current, isFeatures, hasFailed] = await Promise.all([
      read($, commits),
      read($, branch),
      read($, onlyFeatures),
      read($, error),
    ])
    const shown = isFeatures ? list.filter(c => c.type === 'feat') : list
    // Cada commit ocupa 3 linhas (com a margem); o resto é cabeçalho e rodapé.
    const room = Math.max(1, Math.floor(((e.viewport?.rows ?? 24) - 6) / 3))

    const pill = (key: string, label: string, isOn: boolean, onPress: () => unknown) => (
      <Button key={key} plain label={label} onPress={onPress}>
        <Text bold={isOn} color={isOn ? 'claude' : MUTED}>{`${isOn ? '●' : '○'} ${label}`}</Text>
      </Button>
    )
    const row = (c: Commit) => (
      <Box key={c.hash} flexDirection="column" marginTop={1}>
        <Text>
          <Text bold color="claude">{c.short}</Text>
          {'  '}
          <Text color={TYPE_COLOR[c.type] ?? MUTED}>{c.type + (c.isBreaking ? '!' : '')}</Text>
          {c.scope !== '' && <Text color={MUTED}>{` (${c.scope})`}</Text>}
          {'  '}
          <Text bold color={FG}>{c.title}</Text>
        </Text>
        <Text color={MUTED}>{`  ⎇ ${c.branch} · ${clock(c.at)}`}</Text>
      </Box>
    )

    return (
      <Box flexDirection="column" backgroundColor={BG} paddingX={1} minHeight={Math.max(1, (e.viewport?.rows ?? 24) - 2)}>
        <Box columnGap={3}>
          {pill('only-features', t.features, isFeatures, () => update($, onlyFeatures, () => true))}
          {pill('all-commits', t.all, !isFeatures, () => update($, onlyFeatures, () => false))}
          <Box flexGrow={1} />
          <Button key="refresh" plain label={t.refresh} onPress={() => sync($)}>
            <Text color={MUTED}>{`↻ ${t.refresh}`}</Text>
          </Button>
        </Box>
        {current !== '' && <Text color={MUTED}>{`${t.on} ⎇ ${current} · ${shown.length}`}</Text>}
        {hasFailed && <Text color="warning">{t.noRepo}</Text>}
        {!hasFailed && shown.length === 0 && <Text color={MUTED}>{isFeatures && list.length > 0 ? t.emptyFeatures : t.empty}</Text>}
        {shown.slice(0, room).map(row)}
      </Box>
    )
  })
}

