import type { Commit } from '../../types'

// Um commit por registro: hash, data (epoch s) e assunto, separados por \x1f.
export const LOG_FORMAT = '%H%x1f%ct%x1f%s%x1e'

const CONVENTIONAL = /^(\w+)(?:\(([^)]*)\))?(!)?:\s*(.+)$/

export function parseSubject(subject: string) {
  const m = CONVENTIONAL.exec(subject)
  if (m === null) return { type: 'other', scope: '', title: subject, isBreaking: false }
  return { type: m[1]!.toLowerCase(), scope: m[2] ?? '', title: m[4]!, isBreaking: m[3] === '!' }
}

export function parseLog(stdout: string, branch: string): Commit[] {
  return stdout
    .split('\x1e')
    .map(record => record.trim())
    .filter(record => record !== '')
    .map(record => {
      const [hash = '', seconds = '0', ...rest] = record.split('\x1f')
      return { hash, short: hash.slice(0, 7), at: Number(seconds) * 1000, branch, ...parseSubject(rest.join('\x1f')) }
    })
}

// Junta o log novo ao que já se conhece: um commit já visto mantém a branch
// em que foi visto pela primeira vez; os novos ganham a branch atual.
// ponytail: um amend/rebase gera outro hash e o antigo fica na lista; limite de 200.
export function mergeCommits(known: Commit[], fresh: Commit[]): Commit[] {
  const seen = new Set(known.map(c => c.hash))
  return [...fresh.filter(c => !seen.has(c.hash)), ...known].sort((a, b) => b.at - a.at).slice(0, 200)
}

