export type Commit = {
  hash: string
  short: string
  /** Conventional-commit type (feat, fix, chore...), or `other`. */
  type: string
  scope: string
  title: string
  isBreaking: boolean
  /** Commit time, epoch milliseconds. */
  at: number
  /** Branch checked out when the commit was first seen. */
  branch: string
}

declare module 'claude-code' {
  interface PluginState {
    'feature-tracker': {
      since: number | null
      commits: Commit[]
      branch: string
      onlyFeatures: boolean
      error: boolean
    }
  }
}
